#pragma once

// The parents' page from the flash. `board_build.embed_txtfiles` in platformio.ini binds web/index.html into
// the firmware as data and the linker provides its start and end. There is one source of the page,
// web/index.html, generated by scripts/gen_web.py (CI checks that it is current), and the simulator reads
// the same file from disk.

#include <cstddef>
#include <cstdint>

#include <web/WebAssets.h>

extern const uint8_t kWebIndexStart[] asm("_binary_web_index_html_start");
extern const uint8_t kWebIndexEnd[] asm("_binary_web_index_html_end");

class FlashAssets : public WebAssets {
public:
  const char* indexHtml(size_t& length) override {
    // embed_txtfiles appends a zero byte; it is not part of the page.
    length = (size_t)(kWebIndexEnd - kWebIndexStart) - 1;
    return reinterpret_cast<const char*>(kWebIndexStart);
  }
};
